<include file="Public:header"/>		<div class="mainbox">			<div id="nav" class="mainnav_title">				<ul>					<a href="{pigcms{:U('User/agent_money_list')}" class="on">【{pigcms{$money_list.user.nickname}】的佣金记录列表</a>				</ul>			</div>			<!--table class="search_table" width="100%">				<tr>					<td>						<form action="{pigcms{:U('User/agent_money_list')}" method="get">							<input type="hidden" name="c" value="User"/>							<input type="hidden" name="a" value="agent_money_list"/>							筛选: <input type="text" name="keyword" class="input-text" value="{pigcms{$_GET['keyword']}"/>							<select name="searchtype">								<option value="uid" <if condition="$_GET['searchtype'] eq 'uid'">selected="selected"</if>>用户ID</option>								<option value="nickname" <if condition="$_GET['searchtype'] eq 'nickname'">selected="selected"</if>>昵称</option>								<option value="phone" <if condition="$_GET['searchtype'] eq 'phone'">selected="selected"</if>>手机号</option>							</select>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;																											<input type="submit" style="margin-right:20px;" value="查询" class="button"/>													</form>											</td>				</tr>			</table-->			<form name="myform" id="myform" action="" method="post">				<div class="table-list">					<table width="100%" cellspacing="0">						<colgroup>							<col/>							<col/>							<col/>							<col/>							<col/>							<col width="180" align="center"/>						</colgroup>						<thead>							<tr>																<th>ID</th>								<th class="textcenter">用户信息</th>								<th class="textcenter">商家信息</th>								<th class="textcenter">佣金</th>								<th class="textcenter">描述</th>								<th class="textcenter">分佣时间</th>							</tr>						</thead>						<tbody>							<if condition="is_array($money_list['money_list'])">								<volist name="money_list['money_list']" id="vo">									<tr>										<td>{pigcms{$vo.id}</td>										<td class="textcenter">{pigcms{$vo.nickname}</td>										<td class="textcenter">{pigcms{$vo.name}</td>										<td class="textcenter">{pigcms{$config['Currency_symbol']}{pigcms{$vo.money|floatval=###}</td>										<td class="textcenter">{pigcms{$vo.des}</td>										<td class="textcenter">										{pigcms{$vo['add_time']|date='Y-m-d H:i:s',###}										</td>									</tr>								</volist>								<tr><td class="textcenter pagebar" colspan="11">{pigcms{$money_list.pagebar}</td></tr>							<else/>								<tr><td class="textcenter red" colspan="11">列表为空！</td></tr>							</if>						</tbody>					</table>				</div>			</form>		</div>		<script>		 var url = "{pigcms{$config.site_url}"    var export_url = "{pigcms{:U('User/export')}"</script><script type="text/javascript" src="{pigcms{$static_public}js/export.js"> </script><include file="Public:footer"/>